default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows Nt\Terminal Services' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('MaxIdleTime', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_idle_rdp_session_disconnect_time)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows Nt\Terminal Services [MaxIdleTime]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows Nt\Terminal Services')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows Nt\Terminal Services' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows Nt\Terminal Services' -Name 'MaxIdleTime' -Value $ODV_idle_rdp_session_disconnect_time -PropertyType DWord -Force | Out-Null
exit 0
